KG_CODE("f:native/overlay/AgentOverlay.cs","// autoskill agent overlay — native visual layer (C# / WPF).\n//\n// v2 (2026-10-07): the CUA-faithful agent pointer, rebuilt natively after the\n// owner directive. Motion and visuals follow the cua-driver reference\n// (cursor-overlay crate) as extracted line-by-line by the spec agents:\n//   - Dubins arc-straight-arc paths, turn radius 80 pt\n//   - speed profile 16u^2(1-u)^2 (peak 900 pt/s, floors 300/200 pt/s)\n//   - spring settle k = spring*400 = 288, c = spring*20 = 14.4, 4 substeps,\n//     impulse 0.5*end speed along the end tangent, settle < 0.3 pt / 2 pt/s\n//   - artwork centre = click point + 16 pt at 45 deg (CLICK_OFFSET)\n//   - arrow: closed cubic bezier on a 128-unit canvas shown at 42 pt,\n//     white outline 5/128, bloom glow; brand fill #1A8E88 (owner: same color)\n//   - badge pill: <=188x28 capsule 25 pt below the arrow, label + two chips\n//     (delivery filled, target outlined), hold 2.0 s, fade 0.4 s smoothstep,\n//     hover reveal within 34.44 pt; no state dot (CUA design)\n//   - idle hide after 20 s, 180 ms fade; resting bob 4 s cycle\n//   - click pulse: 0.25 s state + 0.67 s squash-and-rays animation\n// The real OS cursor is never hidden: the arrow is additive, exactly like\n// cua-driver (the OS pointer receives the input, the arrow is what you read).\n// Build: native/overlay/build.cmd. Attribution: CUA-LICENSE.md.\n\nusing System;\nusing System.Collections.Generic;\nusing System.Globalization;\nusing System.IO;\nusing System.Runtime.InteropServices;\nusing System.Threading;\nusing System.Web.Script.Serialization;\nusing System.Windows;\nusing System.Windows.Controls;\nusing System.Windows.Input;\nusing System.Windows.Interop;\nusing System.Windows.Media;\nusing System.Windows.Media.Animation;\nusing System.Windows.Media.Imaging;\nusing System.Windows.Shapes;\nusing WPath = System.Windows.Shapes.Path;\nusing System.Windows.Threading;\n\nnamespace Autoskill.Overlay\n{\n    internal static class Native\n    {\n        [DllImport(\"user32.dll\")] internal static extern int GetWindowLongPtrW(IntPtr hWnd, int nIndex);\n        [DllImport(\"user32.dll\")] internal static extern int SetWindowLongPtrW(IntPtr hWnd, int nIndex, int dwNewLong);\n        [DllImport(\"user32.dll\")] internal static extern bool SetWindowDisplayAffinity(IntPtr hWnd, uint dwAffinity);\n        [DllImport(\"user32.dll\")] internal static extern int GetSystemMetrics(int nIndex);\n        [DllImport(\"user32.dll\")] internal static extern bool GetCursorPos(out POINT pt);\n        [DllImport(\"user32.dll\")] internal static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int x, int y, int cx, int cy, uint uFlags);\n        [DllImport(\"user32.dll\")] internal static extern IntPtr GetWindow(IntPtr hWnd, uint uCmd);\n        [DllImport(\"user32.dll\")] internal static extern bool IsWindow(IntPtr hWnd);\n\n        [StructLayout(LayoutKind.Sequential)]\n        internal struct POINT { public int X; public int Y; }\n\n        internal const int GWL_EXSTYLE = -20;\n        internal const int WS_EX_TRANSPARENT = 0x00000020;\n        internal const int WS_EX_TOOLWINDOW = 0x00000080;\n        internal const int WS_EX_NOACTIVATE = 0x08000000;\n        internal const uint WDA_EXCLUDEFROMCAPTURE = 0x11;\n    }\n\n    internal static class States\n    {\n        // One vocabulary, shared with the Python desktop bar and the browser\n        // toolbar: aiming/acting sky, verifying amber, done green,\n        // stuck red, approval violet.\n        private static readonly Dictionary<string, Color> Map =\n            new Dictionary<string, Color>(StringComparer.OrdinalIgnoreCase)\n        {\n            { \"aiming\",    Color.FromRgb(0x22, 0xc5, 0x5e) },\n            { \"acting\",    Color.FromRgb(0x22, 0xc5, 0x5e) },\n            { \"verifying\", Color.FromRgb(0xfb, 0xbf, 0x24) },\n            { \"done\",      Color.FromRgb(0x34, 0xd3, 0x99) },\n            { \"stuck\",     Color.FromRgb(0xf8, 0x71, 0x71) },\n            { \"approval\",  Color.FromRgb(0xa7, 0x8b, 0xfa) },\n        };\n\n        internal static Color ColorOf(string state)\n        {\n            Color c;\n            if (state != null && Map.TryGetValue(state, out c)) return c;\n            return Map[\"acting\"];\n        }\n    }\n\n    // ------------------------------------------------------------------ Dubins\n    /// Arc-straight-arc path planner, ported from cua-driver\n    /// cursor-overlay/src/path_planner.rs (shortest of the six words,\n    /// sampled by arc length). All units are logical points (pt).\n    internal sealed class DubinsPath\n    {\n        private abstract class Seg { internal abstract double Len { get; } internal abstract Sample Pos(double s); }\n        private sealed class Straight : Seg\n        {\n            internal double X, Y, Dx, Dy, Len2;\n            internal override double Len { get { return Len2; } }\n            internal override Sample Pos(double s)\n            {\n                return new Sample(X + Dx * s, Y + Dy * s, Math.Atan2(Dy, Dx));\n            }\n        }\n        private sealed class Arc : Seg\n        {\n            internal double Cx, Cy, A0, Dir, R, Len2;   // Dir: +1 CCW (left), -1 CW\n            internal override double Len { get { return Len2; } }\n            internal override Sample Pos(double s)\n            {\n                double a = A0 + Dir * (s / R);\n                return new Sample(Cx + R * Math.Cos(a), Cy + R * Math.Sin(a), a + Dir * (Math.PI / 2));\n            }\n        }\n        internal struct Sample { internal double X, Y, Heading; internal Sample(double x, double y, double h) { X = x; Y = y; Heading = h; } }\n\n        private readonly List<Seg> _segs = new List<Seg>();\n        private readonly double[] _cum;\n        internal readonly double Length;\n\n        private DubinsPath(List<Seg> segs)\n        {\n            _segs = segs;\n            _cum = new double[segs.Count + 1];\n            for (int i = 0; i < segs.Count; i++) _cum[i + 1] = _cum[i] + segs[i].Len;\n            Length = _cum[segs.Count];\n        }\n\n        internal Sample SampleAt(double s)\n        {\n            if (s <= 0) s = 0;\n            if (s >= Length) s = Math.Max(0, Length - 0.000001);\n            for (int i = 0; i < _segs.Count; i++)\n            {\n                if (s <= _cum[i + 1] || i == _segs.Count - 1)\n                    return _segs[i].Pos(s - _cum[i]);\n            }\n            return new Sample(0, 0, 0);\n        }\n\n        internal static DubinsPath Plan(double x0, double y0, double th0,\n                                        double x1, double y1, double th1, double r)\n        {\n            if (r < 1) r = 1;\n            if (r > 1000) r = 1000;\n            double dx = x1 - x0, dy = y1 - y0;\n            if (Math.Sqrt(dx * dx + dy * dy) < 0.5)\n                return null;                        // caller falls back to a hold\n            List<Seg> best = null; double bestLen = double.PositiveInfinity;\n            List<Seg> w;\n            w = Word(x0, y0, th0, x1, y1, th1, r, true, true);   TryKeep(w, ref best, ref bestLen);\n            w = Word(x0, y0, th0, x1, y1, th1, r, false, false); TryKeep(w, ref best, ref bestLen);\n            w = Word(x0, y0, th0, x1, y1, th1, r, true, false);  TryKeep(w, ref best, ref bestLen);\n            w = Word(x0, y0, th0, x1, y1, th1, r, false, true);  TryKeep(w, ref best, ref bestLen);\n            w = Triplet(x0, y0, th0, x1, y1, th1, r, true);      TryKeep(w, ref best, ref bestLen);\n            w = Triplet(x0, y0, th0, x1, y1, th1, r, false);     TryKeep(w, ref best, ref bestLen);\n            if (best == null)\n                return null;\n            return new DubinsPath(best);\n        }\n\n        private static void TryKeep(List<Seg> w, ref List<Seg> best, ref double bestLen)\n        {\n            if (w == null) return;\n            double len = 0;\n            foreach (Seg s in w) len += s.Len;\n            if (len < bestLen) { bestLen = len; best = w; }\n        }\n\n        private static double Norm(double a)\n        {\n            a = a % (2 * Math.PI);\n            if (a < 0) a += 2 * Math.PI;\n            return a;\n        }\n\n        // Circle centres for a pose: left normal = (-sin, cos).\n        private static void Centres(double x, double y, double th, double r,\n                                    out double lx, out double ly, out double rx, out double ry)\n        {\n            double nx = -Math.Sin(th), ny = Math.Cos(th);\n            lx = x + r * nx; ly = y + r * ny;\n            rx = x - r * nx; ry = y - r * ny;\n        }\n\n        // CSC words. firstLeft/lastLeft pick the circle side per word.\n        private static List<Seg> Word(double x0, double y0, double th0,\n                                      double x1, double y1, double th1, double r,\n                                      bool firstLeft, bool lastLeft)\n        {\n            double ax0, ay0, bx0, by0, ax1, ay1, bx1, by1;\n            Centres(x0, y0, th0, r, out ax0, out ay0, out bx0, out by0);\n            Centres(x1, y1, th1, r, out ax1, out ay1, out bx1, out by1);\n            double c0x = firstLeft ? ax0 : bx0, c0y = firstLeft ? ay0 : by0;\n            double c1x = lastLeft ? ax1 : bx1, c1y = lastLeft ? ay1 : by1;\n            double vx = c1x - c0x, vy = c1y - c0y;\n            double d = Math.Sqrt(vx * vx + vy * vy);\n\n            double tx, ty;                                   // tangent points\n            if (firstLeft == lastLeft)\n            {\n                // External tangent, offset r to the same side; direction = c1-c0.\n                if (d < 0.001) return null;\n                double ux = vx / d, uy = vy / d;\n                double nx = -uy, ny = ux;                    // left of direction\n                if (!firstLeft) { nx = -nx; ny = -ny; }\n                tx = c0x + r * nx; ty = c0y + r * ny;\n            }\n            else\n            {\n                // Internal tangent, offset r to opposite sides; needs d >= 2r.\n                if (d < 2 * r * 0.999) return null;\n                double baseAng = Math.Atan2(vy, vx);\n                double c = 2 * r / d;\n                if (c > 1) c = 1;\n                double off = Math.Acos(c);\n                // two candidate normals; take the one pointing \"left of c\" family\n                double nAng = baseAng + (firstLeft ? off : -off);\n                double nx = Math.Cos(nAng), ny = Math.Sin(nAng);\n                tx = c0x + r * nx; ty = c0y + r * ny;\n            }\n            // tangent end = same offset applied to the second circle\n            double t2x = tx + (c1x - c0x) * (firstLeft == lastLeft ? 1 : 0), t2y = ty;\n            if (firstLeft == lastLeft)\n            {\n                // straight from (tx,ty) along unit(c1-c0); recompute exactly\n                double ux = vx / d, uy = vy / d;\n                Straight st = new Straight { X = tx, Y = ty, Dx = ux, Dy = uy, Len2 = d };\n                Arc a1 = ArcFrom(x0, y0, c0x, c0y, tx, ty, r, firstLeft);\n                Arc a2 = ArcTo(t2x, t2y, c1x, c1y, x1, y1, r, lastLeft);\n                if (a1 == null || a2 == null) return null;\n                if (st.Len2 < -0.000001) return null;\n                return new List<Seg> { a1, st, a2 };\n            }\n            // internal: second tangent point mirrored on the second circle\n            // tangent direction = t2 - t1 where t2 = c1 - r*n (opposite side)\n            double n2x = (tx - c0x) / r, n2y = (ty - c0y) / r;    // unit normal used\n            double s2x = c1x - r * n2x, s2y = c1y - r * n2y;\n            double ddx = s2x - tx, ddy = s2y - ty;\n            double dd = Math.Sqrt(ddx * ddx + ddy * ddy);\n            if (dd < 0.001) return null;\n            Straight st2 = new Straight { X = tx, Y = ty, Dx = ddx / dd, Dy = ddy / dd, Len2 = dd };\n            Arc b1 = ArcFrom(x0, y0, c0x, c0y, tx, ty, r, firstLeft);\n            Arc b2 = ArcTo(s2x, s2y, c1x, c1y, x1, y1, r, lastLeft);\n            if (b1 == null || b2 == null) return null;\n            return new List<Seg> { b1, st2, b2 };\n        }\n\n        // CCC words (RLR / LRL): middle circle of radius r touching both.\n        private static List<Seg> Triplet(double x0, double y0, double th0,\n                                         double x1, double y1, double th1, double r, bool left)\n        {\n            double ax0, ay0, bx0, by0, ax1, ay1, bx1, by1;\n            Centres(x0, y0, th0, r, out ax0, out ay0, out bx0, out by0);\n            Centres(x1, y1, th1, r, out ax1, out ay1, out bx1, out by1);\n            double c0x = left ? ax0 : bx0, c0y = left ? ay0 : by0;\n            double c1x = left ? ax1 : bx1, c1y = left ? ay1 : by1;\n            double vx = c1x - c0x, vy = c1y - c0y;\n            double d = Math.Sqrt(vx * vx + vy * vy);\n            if (d < 0.001 || d > 4 * r * 0.999) return null;\n            double h = Math.Sqrt(Math.Max(0, 4 * r * r - d * d / 4));\n            double mx = (c0x + c1x) / 2 - vy / d * h * (left ? 1 : -1);\n            double my = (c0y + c1y) / 2 + vx / d * h * (left ? 1 : -1);\n            // touch point between circle0 and middle\n            double t0x = (c0x + mx) / 2, t0y = (c0y + my) / 2;\n            double t1x = (mx + c1x) / 2, t1y = (my + c1y) / 2;\n            Arc a1 = ArcFrom(x0, y0, c0x, c0y, t0x, t0y, r, left);\n            Arc a2 = ArcThrough(t0x, t0y, mx, my, t1x, t1y, r, !left);\n            Arc a3 = ArcTo(t1x, t1y, c1x, c1y, x1, y1, r, left);\n            if (a1 == null || a2 == null || a3 == null) return null;\n            return new List<Seg> { a1, a2, a3 };\n        }\n\n        // Arc on circle (cx,cy) from the pose point to the tangent point,\n        // turning left (ccw) or right (cw); null when degenerate.\n        private static Arc ArcFrom(double px, double py, double cx, double cy,\n                                   double tx, double ty, double r, bool left)\n        {\n            double a0 = Math.Atan2(py - cy, px - cx);\n            double a1 = Math.Atan2(ty - cy, tx - cx);\n            double sweep = left ? Norm(a1 - a0) : Norm(a0 - a1);\n            if (sweep < 0.000001) sweep = 0.000001;\n            return new Arc { Cx = cx, Cy = cy, A0 = a0, Dir = left ? 1 : -1, R = r, Len2 = sweep * r };\n        }\n\n        private static Arc ArcTo(double tx, double ty, double cx, double cy,\n                                 double px, double py, double r, bool left)\n        {\n            double a0 = Math.Atan2(ty - cy, tx - cx);\n            double a1 = Math.Atan2(py - cy, px - cx);\n            double sweep = left ? Norm(a1 - a0) : Norm(a0 - a1);\n            if (sweep < 0.000001) sweep = 0.000001;\n            return new Arc { Cx = cx, Cy = cy, A0 = a0, Dir = left ? 1 : -1, R = r, Len2 = sweep * r };\n        }\n\n        private static Arc ArcThrough(double fx, double fy, double cx, double cy,\n                                      double tx, double ty, double r, bool left)\n        {\n            double a0 = Math.Atan2(fy - cy, fx - cx);\n            double a1 = Math.Atan2(ty - cy, tx - cx);\n            double sweep = left ? Norm(a1 - a0) : Norm(a0 - a1);\n            if (sweep < 0.000001) sweep = 0.000001;\n            return new Arc { Cx = cx, Cy = cy, A0 = a0, Dir = left ? 1 : -1, R = r, Len2 = sweep * r };\n        }\n    }\n\n    // ------------------------------------------------------------ pointer core\n    /// The agent pointer: physics + badge state, ticked per frame.\n    /// Units: logical points (WPF DIPs) relative to the stage origin.\n    internal sealed class PointerState\n    {\n        // CUA constants (spec 2026-10-07).\n        internal const double PeakSpeed = 900, MinStart = 300, MinEnd = 200;\n        internal const double TurnRadius = 80;\n        internal const double SpringK = 288.0, SpringC = 14.4;   // spring 0.72\n        internal const double ClickOffset = 16.0;                // along 45 deg\n        internal const double EndHeading = Math.PI / 4;\n        internal const double IdleHideSecs = 20.0, IdleFadeSecs = 0.18;\n        internal const double BadgeHold = 2.0, BadgeFade = 0.4;\n        internal const double HoverRadius = 34.44;\n        // Owner directive 2026-10-08: a modern, original design, slightly\n        // smaller than the cua-driver artwork, same brand colour, same motion.\n        internal const double DisplaySize = 36.0;   // pt (cua-driver uses 42)\n\n        internal double X = -200, Y = -200;                      // sentinel\n        internal double Heading = Math.PI / 4;\n        internal bool Visible;\n\n        private DubinsPath _path;\n        private double _dist;\n        private double _springOx, _springOy, _springVx, _springVy;\n        private bool _springing;\n        private double _springTgtX, _springTgtY;\n\n        internal double ClickT = -1;                             // 0..1, -1 = off\n        internal double ClickAnim = -1;                          // 0..0.67 s\n        internal double IdleSecs, IdleAlpha = 1;\n        internal double BobT;\n        internal double CmdAlpha = 1;\n        // Arrival protocol (stage 1, 2026-10-09): the renderer reports the\n        // true end of each glide so input can wait for it (CUA oneshots).\n        internal long MoveId = -1;\n        internal bool Arrived;\n        internal double PlannedLen;\n\n        // Badge\n        internal string Label = \"\";\n        internal string Delivery = \"\", Target = \"\";             // \"\", chips off\n        internal string Action = \"\";\n        internal double BadgeT = 1e9;                            // since reveal\n        internal double ChipFadeT = 1e9;\n        internal bool ChipsOn;\n        internal bool RevealedOnce;\n\n        internal bool NeedsFrame\n        {\n            get\n            {\n                return _path != null || _springing || ClickT >= 0 || ClickAnim >= 0\n                    || Visible && IdleAlpha > 0.004 && IdleSecs < IdleHideSecs\n                    || BadgeAlpha < 1 && BadgeT < BadgeHold + BadgeFade + 0.05\n                    || ChipAlpha > 0.004;\n            }\n        }\n\n        internal double BadgeAlpha\n        {\n            get\n            {\n                double a;\n                if (BadgeT < BadgeHold) a = 1;\n                else if (BadgeT < BadgeHold + BadgeFade)\n                {\n                    double u = (BadgeT - BadgeHold) / BadgeFade;\n                    a = 1 - u * u * (3 - 2 * u);                 // smoothstep\n                }\n                else a = 0;\n                return Math.Max(a, ChipAlpha);\n            }\n        }\n\n        internal double ChipAlpha\n        {\n            get\n            {\n                if (ChipsOn) return 1;\n                if (ChipFadeT < BadgeFade)\n                {\n                    double u = ChipFadeT / BadgeFade;\n                    return 1 - u * u * (3 - 2 * u);\n                }\n                return 0;\n            }\n        }\n\n        internal bool InFlight { get { return _path != null || _springing; } }\n\n        internal void Reveal()\n        {\n            Visible = true;\n            IdleSecs = 0;\n            IdleAlpha = 1;\n        }\n\n        /// Glide to a click point (tip position). Plans the Dubins path from\n        /// the current artwork centre toward centre = tip + 16pt at 45 deg.\n        internal void MoveTo(double tipX, double tipY, double stageW, double stageH)\n        {\n            double tx = tipX + Math.Cos(EndHeading) * ClickOffset;\n            double ty = tipY + Math.Sin(EndHeading) * ClickOffset;\n            if (!RevealedOnce)\n            {\n                // seed 140 pt up-left of the target, clamped on stage\n                double sx = tx - 140, sy = ty - 140;\n                if (sx < 4 || sy < 4) { sx = tx + 140; sy = ty + 140; }\n                sx = Math.Max(4, Math.Min(stageW - 4, sx));\n                sy = Math.Max(4, Math.Min(stageH - 4, sy));\n                X = sx; Y = sy; Heading = EndHeading;\n                RevealedOnce = true;\n            }\n            Reveal();\n            if (X < -100 || Y < -100) { X = tx; Y = ty; Heading = EndHeading; return; }\n            double dx = tx - X, dy = ty - Y;\n            if (Math.Sqrt(dx * dx + dy * dy) < 0.5) { Snap(tx, ty); return; }\n            double th0 = Heading + Math.PI;\n            double th1 = EndHeading + Math.PI;\n            DubinsPath p = DubinsPath.Plan(X, Y, th0, tx, ty, th1, TurnRadius);\n            if (p == null) { Snap(tx, ty); return; }\n            _path = p; _dist = 0;\n            PlannedLen = p.Length;\n            Arrived = false;\n            _springing = false;\n        }\n\n        internal void Snap(double tipX, double tipY)\n        {\n            X = tipX + Math.Cos(EndHeading) * ClickOffset;\n            Y = tipY + Math.Sin(EndHeading) * ClickOffset;\n            Heading = EndHeading;\n            _path = null; _springing = false;\n            Arrived = true;                      // a snap is an instant arrival\n            if (RevealedOnce) Reveal();\n        }\n\n        internal void Pulse()\n        {\n            ClickT = 0;\n            ClickAnim = 0;\n            IdleSecs = 0;\n            IdleAlpha = 1;\n            Visible = true;\n        }\n\n        internal void BeginBadge(string label, string delivery, string target, string action)\n        {\n            Label = label;\n            Delivery = delivery;\n            Target = target;\n            Action = action;\n            BadgeT = 0;\n            ChipsOn = true;\n            ChipFadeT = 1e9;\n            // A badge is activity (CUA render_state.rs:646-745): pointer and\n            // badge reveal together and the idle clock restarts, so the pill\n            // can never outlive the arrow.\n            IdleSecs = 0;\n            IdleAlpha = 1;\n            Visible = true;\n            RevealedOnce = true;\n        }\n\n        internal void EndBadge()\n        {\n            if (ChipsOn) { ChipsOn = false; ChipFadeT = 0; }\n        }\n\n        /// One physics step. dt already clamped by the caller.\n        internal void Tick(double dt)\n        {\n            if (_path != null)\n            {\n                double len = Math.Max(1.0, _path.Length);\n                double u = Math.Min(1.0, _dist / len);\n                double profile = 16 * u * u * (1 - u) * (1 - u);\n                double floor = u < 0.5 ? MinStart : MinEnd;\n                double speed = Math.Max(floor, floor + (PeakSpeed - floor) * profile);\n                _dist += speed * dt;\n                if (_dist >= len)\n                {\n                    DubinsPath.Sample s = _path.SampleAt(len);\n                    double endSpeed = Math.Max(MinEnd, speed);\n                    double vh = s.Heading;\n                    _springOx = 0; _springOy = 0;\n                    _springVx = endSpeed * 0.5 * Math.Cos(vh);\n                    _springVy = endSpeed * 0.5 * Math.Sin(vh);\n                    _springTgtX = s.X; _springTgtY = s.Y;\n                    X = s.X; Y = s.Y;\n                    Heading = EndHeading;\n                    _path = null;\n                    Arrived = true;              // visible glide landed (CUA fires oneshots here; spring excluded)\n                    _springing = true;\n                }\n                else\n                {\n                    DubinsPath.Sample s = _path.SampleAt(_dist);\n                    X = s.X; Y = s.Y;\n                    Heading = s.Heading + Math.PI;               // tip trails the tangent\n                }\n            }\n            else if (_springing)\n            {\n                const int substeps = 4;\n                double sdt = dt / substeps;\n                for (int i = 0; i < substeps; i++)\n                {\n                    _springVx += (-SpringK * _springOx - SpringC * _springVx) * sdt;\n                    _springVy += (-SpringK * _springOy - SpringC * _springVy) * sdt;\n                    _springOx += _springVx * sdt;\n                    _springOy += _springVy * sdt;\n                }\n                X = _springTgtX + _springOx;\n                Y = _springTgtY + _springOy;\n                double o = Math.Sqrt(_springOx * _springOx + _springOy * _springOy);\n                double v = Math.Sqrt(_springVx * _springVx + _springVy * _springVy);\n                if (o < 0.3 && v < 2.0)\n                {\n                    X = _springTgtX; Y = _springTgtY;\n                    _springing = false;\n                }\n            }\n\n            if (ClickT >= 0) { ClickT += dt * 4; if (ClickT >= 1) ClickT = -1; }\n            if (ClickAnim >= 0) { ClickAnim += dt; if (ClickAnim > 0.67) ClickAnim = -1; }\n\n            bool activity = _path != null || _springing || ClickT >= 0 || ClickAnim >= 0;\n            if (Visible)\n            {\n                if (activity) { IdleSecs = 0; IdleAlpha = 1; BobT += dt; }\n                else\n                {\n                    IdleSecs += dt;\n                    BobT += dt;\n                    if (IdleSecs > IdleHideSecs)\n                    {\n                        double f = (IdleSecs - IdleHideSecs) / IdleFadeSecs;\n                        IdleAlpha = Math.Max(0, 1 - f);\n                        if (IdleAlpha <= 0.004) { IdleAlpha = 0; } // parked\n                    }\n                }\n            }\n            BadgeT += dt;\n            if (!ChipsOn && ChipFadeT < BadgeFade + 0.05) ChipFadeT += dt;\n            // Once the badge has fully faded and nothing is active, clear it\n            // so hover can never resurrect a stale label (stage 1 fix).\n            if (!ChipsOn && Label.Length > 0\n                && BadgeT > BadgeHold + BadgeFade && ClickT < 0)\n            {\n                Label = \"\"; Delivery = \"\"; Target = \"\"; Action = \"\";\n            }\n        }\n\n        // Resting bob (owner design 2026-10-08), canvas units -> pt.\n        internal void Bob(out double dx, out double dy, out double rotDeg)\n        {\n            double scale = DisplaySize / 128.0;\n            double prog = (BobT % 4.0) / 4.0;\n            double ang = prog * 2 * Math.PI;\n            dx = 5 * Math.Sin(ang) * scale;\n            dy = (6 * Math.Cos(ang) - 5) * scale;\n            rotDeg = 2.5 * Math.Cos(ang);\n        }\n    }\n\n    internal sealed class OverlayApp : Application\n    {\n        private const double CursorSize = 32;\n\n        private Window _stage;                  // full-screen: cursor+trails+glow\n        private Canvas _canvas;\n        private Image _cursor;\n        private TranslateTransform _cursorPos;\n        private Border _glow;\n        private Window _bar;\n        private Border _barPill;\n        private Ellipse _barDot;\n        private TextBlock _barText;\n        private TranslateTransform _barSlide;\n        private DispatcherTimer _barIdle;       // bar auto-hide\n        private double _pixelToDipX = 1, _pixelToDipY = 1;\n        private double _screenLeft, _screenTop;\n        private double _stageW, _stageH;\n        private DateTime _lastFrame = DateTime.UtcNow;\n        private bool _frameHooked;\n\n        // agent pointer (CUA rebuild)\n        private readonly PointerState _pt = new PointerState();\n        private Canvas _arrowRoot;              // centre-anchored, rotates\n        private ScaleTransform _arrowSquash;\n        private RotateTransform _arrowRot;\n        private WPath _arrowBody;\n        private Canvas _cue;                    // action cue glyphs\n        private string _cueKind = \"\";\n        private double _cueT;\n        private Canvas _pillRoot;               // badge, never rotates\n        private TranslateTransform _pillPos;\n        private Border _pillCapsule;\n        private TextBlock _pillLabel;\n        private Border _chipDelivery, _chipTarget;\n        private readonly SolidColorBrush _brand =\n            new SolidColorBrush(Color.FromRgb(0x1A, 0x8E, 0x88));   // #1A8E88\n\n        protected override void OnStartup(StartupEventArgs e)\n        {\n            base.OnStartup(e);\n            BuildStage();\n            BuildBar();\n            BuildPointer();\n            _barIdle = new DispatcherTimer { Interval = TimeSpan.FromSeconds(3.5) };\n            _barIdle.Tick += delegate { ShowBar(false); _barIdle.Stop(); };\n            Thread reader = new Thread(ReadLoop) { IsBackground = true };\n            reader.Start();\n        }\n\n        // -- windows ------------------------------------------------------------\n\n        private void BuildStage()\n        {\n            int left = Native.GetSystemMetrics(76), top = Native.GetSystemMetrics(77);\n            int w = Native.GetSystemMetrics(78), h = Native.GetSystemMetrics(79);\n            _screenLeft = left; _screenTop = top;\n            _stage = NewOverlayWindow(w, h);\n            _stage.Left = left; _stage.Top = top;\n            _canvas = new Canvas();\n            _stage.Content = _canvas;\n\n            Color sky = States.ColorOf(\"acting\");\n            _glow = new Border\n            {\n                Width = w - 12, Height = h - 12,\n                CornerRadius = new CornerRadius(24),\n                BorderBrush = new SolidColorBrush(Color.FromRgb(0x20, 0xB2, 0xAA)),\n                BorderThickness = new Thickness(12),\n                Opacity = 0\n            };\n            Canvas.SetLeft(_glow, 6); Canvas.SetTop(_glow, 6);\n            _canvas.Children.Add(_glow);\n\n            _cursorPos = new TranslateTransform();\n            _cursor = new Image\n            {\n                Width = CursorSize, Height = CursorSize,\n                Opacity = 0, RenderTransform = _cursorPos,\n                Stretch = Stretch.Fill, Visibility = Visibility.Hidden\n            };\n            RenderOptions.SetBitmapScalingMode(_cursor, BitmapScalingMode.NearestNeighbor);\n            _canvas.Children.Add(_cursor);\n            _stage.Show();\n            // UIA supplies physical screen pixels; WPF positions are DIPs.\n            // Use the actual composition target, including non-100% DPI.\n            Matrix fromDevice = PresentationSource.FromVisual(_stage).CompositionTarget.TransformFromDevice;\n            _pixelToDipX = fromDevice.M11; _pixelToDipY = fromDevice.M22;\n            _stage.Left = left * _pixelToDipX; _stage.Top = top * _pixelToDipY;\n            _stage.Width = w * _pixelToDipX; _stage.Height = h * _pixelToDipY;\n            _stageW = _stage.Width; _stageH = _stage.Height;\n            _cursor.Width = CursorSize * _pixelToDipX;\n            _cursor.Height = CursorSize * _pixelToDipY;\n            _glow.Width = Math.Max(0, _stage.Width - 12);\n            _glow.Height = Math.Max(0, _stage.Height - 12);\n        }\n\n        private void BuildBar()\n        {\n            _keepTopmost = true;   // b4o: _bar keeps its creation topmost\n            _bar = NewOverlayWindow(460, 48);\n            _keepTopmost = false;\n            int left = Native.GetSystemMetrics(76), top = Native.GetSystemMetrics(77);\n            int w = Native.GetSystemMetrics(78);\n            _bar.Left = left * _pixelToDipX + (w * _pixelToDipX - 460) / 2.0;\n            _bar.Top = top * _pixelToDipY + 24;\n            _bar.Opacity = 0;\n            _bar.Visibility = Visibility.Hidden;\n\n            Color accent = States.ColorOf(\"acting\");\n            _barDot = new Ellipse\n            {\n                Width = 10, Height = 10, Margin = new Thickness(0, 0, 10, 0),\n                Fill = new SolidColorBrush(accent),\n                VerticalAlignment = VerticalAlignment.Center\n            };\n            _barText = new TextBlock\n            {\n                Foreground = new SolidColorBrush(Color.FromRgb(0xe5, 0xe7, 0xeb)),\n                FontFamily = new FontFamily(\"Segoe UI\"), FontSize = 14,\n                VerticalAlignment = VerticalAlignment.Center,\n                TextTrimming = TextTrimming.CharacterEllipsis\n            };\n            StackPanel row = new StackPanel { Orientation = Orientation.Horizontal };\n            row.Children.Add(_barDot);\n            row.Children.Add(_barText);\n            _barSlide = new TranslateTransform();\n            _barPill = new Border\n            {\n                CornerRadius = new CornerRadius(24),\n                Background = new SolidColorBrush(Color.FromArgb(215, 0x0f, 0x17, 0x2a)),\n                BorderBrush = new SolidColorBrush(accent),\n                BorderThickness = new Thickness(2),\n                Padding = new Thickness(18, 0, 18, 0),\n                Child = row,\n                RenderTransform = _barSlide\n            };\n            _bar.Content = _barPill;\n        }\n\n        // -- agent pointer visuals -------------------------------------------------\n\n        private void BuildPointer()\n        {\n            // Arrow root: anchored at artwork centre, rotated by heading.\n            _arrowSquash = new ScaleTransform(1, 1);\n            _arrowRot = new RotateTransform(0);\n            TransformGroup inner = new TransformGroup();\n            inner.Children.Add(_arrowSquash);\n            inner.Children.Add(_arrowRot);\n            _arrowRoot = new Canvas\n            {\n                Width = 0, Height = 0,\n                RenderTransform = inner\n            };\n            // outer placement via Canvas position each frame (cheaper than nested TT)\n            _arrowBody = BuildArrowPath();\n            // bloom glow: two soft shadows in the brand color (GPU)\n            _arrowBody.Effect = BuildBloom();\n            _arrowRoot.Children.Add(_arrowBody);\n            _cue = new Canvas { Width = 0, Height = 0, Opacity = 0 };\n            _arrowRoot.Children.Add(_cue);\n            _canvas.Children.Add(_arrowRoot);\n            Canvas.SetLeft(_arrowRoot, -500); Canvas.SetTop(_arrowRoot, -500);\n            _arrowRoot.Visibility = Visibility.Hidden;\n\n            BuildPill();\n        }\n\n        private WPath BuildArrowPath()\n        {\n            // Autoskill's own arrow (owner directive 2026-10-08): a modern,\n            // angular glyph drawn on the 128-unit canvas pointing UP, clearly\n            // distinct from the cua-driver bezier. Authoring space is centred\n            // on (64,64); the render rotates it to the travel heading.\n            double[,] p = {\n                { 64, 16 },     // tip\n                { 50, 66 },     // left base\n                { 60, 60 },     // left notch\n                { 56, 84 },     // tail bottom-left\n                { 72, 80 },     // tail bottom-right\n                { 68, 56 },     // right notch\n                { 78, 62 },     // right base\n            };\n            double s = PointerState.DisplaySize / 128.0;\n            StreamGeometry g = new StreamGeometry();\n            using (StreamGeometryContext ctx = g.Open())\n            {\n                ctx.BeginFigure(new Point((p[0, 0] - 64) * s, (p[0, 1] - 64) * s),\n                                true, true);\n                for (int i = 1; i < p.GetLength(0); i++)\n                    ctx.LineTo(new Point((p[i, 0] - 64) * s, (p[i, 1] - 64) * s),\n                               true, false);\n            }\n            g.Freeze();\n            WPath pth = new WPath\n            {\n                Data = g,\n                Fill = _brand,\n                Stroke = Brushes.White,\n                StrokeThickness = 4.5 * s,\n                StrokeStartLineCap = PenLineCap.Round,\n                StrokeEndLineCap = PenLineCap.Round,\n                StrokeLineJoin = PenLineJoin.Round\n            };\n            return pth;\n        }\n\n        private System.Windows.Media.Effects.Effect BuildBloom()\n        {\n            // Two-layer approximation of the 8-stroke bloom: inner crisp glow +\n            // outer diffuse halo, both in the brand color.\n            System.Windows.Media.Effects.DropShadowEffect outer = new System.Windows.Media.Effects.DropShadowEffect\n            {\n                Color = _brand.Color, BlurRadius = 22, ShadowDepth = 0,\n                Opacity = 0.55\n            };\n            return outer;\n        }\n\n        private void BuildPill()\n        {\n            _pillRoot = new Canvas { Width = 0, Height = 0 };\n            _pillPos = new TranslateTransform();\n            _pillRoot.RenderTransform = _pillPos;\n\n            // capsule: gradient mixed toward the brand color (session_badge.rs)\n            Color mix0 = Mix(Color.FromRgb(94, 151, 178), _brand.Color, 0.66);\n            Color mix1 = Mix(Color.FromRgb(43, 92, 119), _brand.Color, 0.52);\n            Color mix2 = Mix(Color.FromRgb(13, 27, 38), _brand.Color, 0.26);\n            LinearGradientBrush bg = new LinearGradientBrush();\n            bg.StartPoint = new Point(0, 0); bg.EndPoint = new Point(1, 1);\n            bg.GradientStops.Add(new GradientStop(Color.FromArgb(236, mix0.R, mix0.G, mix0.B), 0));\n            bg.GradientStops.Add(new GradientStop(Color.FromArgb(239, mix1.R, mix1.G, mix1.B), 0.46));\n            bg.GradientStops.Add(new GradientStop(Color.FromArgb(245, mix2.R, mix2.G, mix2.B), 1));\n            Color rim = Mix(Colors.White, _brand.Color, 0.55);\n\n            StackPanel row = new StackPanel { Orientation = Orientation.Horizontal };\n            _pillLabel = new TextBlock\n            {\n                Foreground = Brushes.White,\n                FontFamily = new FontFamily(\"Segoe UI\"), FontSize = 11.5,\n                VerticalAlignment = VerticalAlignment.Center,\n                TextTrimming = TextTrimming.CharacterEllipsis\n            };\n            row.Children.Add(_pillLabel);\n            _chipDelivery = BuildChip(true);\n            _chipTarget = BuildChip(false);\n            row.Children.Add(_chipDelivery);\n            row.Children.Add(_chipTarget);\n\n            _pillCapsule = new Border\n            {\n                CornerRadius = new CornerRadius(14),\n                Background = bg,\n                BorderBrush = new SolidColorBrush(Color.FromArgb(190, rim.R, rim.G, rim.B)),\n                BorderThickness = new Thickness(1),\n                Padding = new Thickness(10, 0, 10, 0),\n                Height = 28,\n                Child = row,\n                VerticalAlignment = VerticalAlignment.Center\n            };\n            _pillCapsule.Effect = new System.Windows.Media.Effects.DropShadowEffect\n            {\n                Color = Colors.Black, BlurRadius = 10, ShadowDepth = 2, Opacity = 0.35\n            };\n            _pillRoot.Children.Add(_pillCapsule);\n            _canvas.Children.Add(_pillRoot);\n            Canvas.SetLeft(_pillRoot, -500); Canvas.SetTop(_pillRoot, -500);\n            _pillRoot.Visibility = Visibility.Hidden;\n        }\n\n        private Border BuildChip(bool delivery)\n        {\n            Border well = new Border\n            {\n                Width = 18, Height = 18,\n                CornerRadius = new CornerRadius(5),\n                Margin = new Thickness(delivery ? 7 : 4, 0, 0, 0),\n                VerticalAlignment = VerticalAlignment.Center,\n                Child = new Canvas()          // real glyph assigned per badge\n            };\n            if (delivery)\n                well.Background = new SolidColorBrush(\n                    Color.FromArgb(220, _brand.Color.R, _brand.Color.G, _brand.Color.B));\n            else\n                well.Background = new SolidColorBrush(Color.FromArgb(22, 255, 255, 255));\n            return well;\n        }\n\n        // Glyph set (badge_glyphs.rs): delivery filled = stack / window;\n        // target outlined = globe (browser) / monitor (desktop).\n        private Canvas GlyphStack()\n        {\n            Canvas c = NewGlyphCanvas();\n            Rectangle back = new Rectangle\n            {\n                Width = 7, Height = 7, RadiusX = 1.5, RadiusY = 1.5,\n                Fill = new SolidColorBrush(Color.FromArgb(148, 255, 255, 255)),\n                Stroke = GlyphStroke(0.72), StrokeThickness = 1.35\n            };\n            Canvas.SetLeft(back, 5.2); Canvas.SetTop(back, 3.4);\n            Rectangle front = new Rectangle\n            {\n                Width = 7, Height = 7, RadiusX = 1.5, RadiusY = 1.5,\n                Fill = Brushes.Transparent,\n                Stroke = GlyphStroke(1.0), StrokeThickness = 1.35\n            };\n            Canvas.SetLeft(front, 3.4); Canvas.SetTop(front, 5.2);\n            c.Children.Add(back); c.Children.Add(front);\n            return c;\n        }\n\n        private Canvas GlyphWindow()\n        {\n            Canvas c = NewGlyphCanvas();\n            Rectangle win = new Rectangle\n            {\n                Width = 10, Height = 9, RadiusX = 1.2, RadiusY = 1.2,\n                Fill = Brushes.Transparent,\n                Stroke = GlyphStroke(1.0), StrokeThickness = 1.35\n            };\n            Canvas.SetLeft(win, 4); Canvas.SetTop(win, 4.5);\n            Line bar = new Line\n            {\n                X1 = 4, Y1 = 7, X2 = 14, Y2 = 7,\n                Stroke = GlyphStroke(1.0), StrokeThickness = 1.35\n            };\n            c.Children.Add(win); c.Children.Add(bar);\n            return c;\n        }\n\n        private Canvas GlyphGlobe()\n        {\n            Canvas c = NewGlyphCanvas();\n            Ellipse globe = new Ellipse\n            {\n                Width = 10, Height = 10, Fill = Brushes.Transparent,\n                Stroke = GlyphStroke(1.0), StrokeThickness = 1.35\n            };\n            Canvas.SetLeft(globe, 4); Canvas.SetTop(globe, 4);\n            Line eq = new Line\n            { X1 = 4, Y1 = 9, X2 = 14, Y2 = 9, Stroke = GlyphStroke(1.0), StrokeThickness = 1.1 };\n            Ellipse meridian = new Ellipse\n            {\n                Width = 4.4, Height = 10, Fill = Brushes.Transparent,\n                Stroke = GlyphStroke(0.8), StrokeThickness = 1.1\n            };\n            Canvas.SetLeft(meridian, 6.8); Canvas.SetTop(meridian, 4);\n            c.Children.Add(globe); c.Children.Add(eq); c.Children.Add(meridian);\n            return c;\n        }\n\n        private Canvas GlyphMonitor()\n        {\n            Canvas c = NewGlyphCanvas();\n            Rectangle mon = new Rectangle\n            {\n                Width = 10, Height = 7.6, RadiusX = 1, RadiusY = 1,\n                Fill = Brushes.Transparent,\n                Stroke = GlyphStroke(1.0), StrokeThickness = 1.35\n            };\n            Canvas.SetLeft(mon, 4); Canvas.SetTop(mon, 3.9);\n            Line stem = new Line { X1 = 9, Y1 = 11.5, X2 = 9, Y2 = 13, Stroke = GlyphStroke(1.0), StrokeThickness = 1.35 };\n            Line base_ = new Line { X1 = 6.5, Y1 = 13, X2 = 11.5, Y2 = 13, Stroke = GlyphStroke(1.0), StrokeThickness = 1.35 };\n            c.Children.Add(mon); c.Children.Add(stem); c.Children.Add(base_);\n            return c;\n        }\n\n        private Canvas NewGlyphCanvas()\n        {\n            Canvas c = new Canvas { Width = 18, Height = 18 };\n            return c;\n        }\n\n        private SolidColorBrush GlyphStroke(double alphaScale)\n        {\n            byte a = (byte)Math.Max(0, Math.Min(255, 238 * alphaScale));\n            return new SolidColorBrush(Color.FromArgb(a, 255, 255, 255));\n        }\n\n        private static Color Mix(Color a, Color b, double towardB)\n        {\n            return Color.FromRgb(\n                (byte)(a.R + (b.R - a.R) * towardB),\n                (byte)(a.G + (b.G - a.G) * towardB),\n                (byte)(a.B + (b.B - a.B) * towardB));\n        }\n\n        // -- frame loop ---------------------------------------------------------\n\n        private void HookFrame()\n        {\n            if (_frameHooked) return;\n            _frameHooked = true;\n            CompositionTarget.Rendering += OnFrame;\n        }\n\n        private void OnFrame(object sender, EventArgs e)\n        {\n            try\n            {\n                DateTime now = DateTime.UtcNow;\n                double dt = (now - _lastFrame).TotalSeconds;\n                _lastFrame = now;\n                if (dt < 0) dt = 0;\n                if (dt > 0.05) dt = 0.05;\n                if (!_pt.Visible && !_pt.InFlight) { ParkIfNeeded(); return; }\n                _pt.Tick(dt);\n                if (_pt.Arrived)\n                {\n                    _pt.Arrived = false;\n                    EmitArrived(_pt.MoveId);\n                }\n                RenderPointer();\n                ParkIfNeeded();\n            }\n            catch { /* never take the tool down */ }\n        }\n\n        private void ParkIfNeeded()\n        {\n            bool any = _pt.Visible || _pt.BadgeAlpha > 0.004 || _pt.ChipAlpha > 0.004;\n            if (!any && _frameHooked)\n            {\n                _arrowRoot.Visibility = Visibility.Hidden;\n                _pillRoot.Visibility = Visibility.Hidden;\n            }\n        }\n\n        private void RenderPointer()\n        {\n            bool showArrow = _pt.Visible && _pt.IdleAlpha > 0.004;\n            _arrowRoot.Visibility = showArrow ? Visibility.Visible : Visibility.Hidden;\n            if (showArrow)\n            {\n                double bx, by, brot;\n                _pt.Bob(out bx, out by, out brot);\n                Canvas.SetLeft(_arrowRoot, _pt.X + bx);\n                Canvas.SetTop(_arrowRoot, _pt.Y + by);\n                // The artwork points UP; rest heading (45 deg) must render it\n                // up-left like a pointer, hence the -90 baseline.\n                _arrowRot.Angle = _pt.Heading * 180.0 / Math.PI - 90.0 + brot;\n                _arrowRoot.Opacity = _pt.IdleAlpha * _pt.CmdAlpha;\n                // click squash-stretch: 100 -> 93(f7/20) -> 103(f12/20) -> 100(f20/20)\n                if (_pt.ClickAnim >= 0)\n                {\n                    double f = _pt.ClickAnim / 0.67 * 20.0;\n                    double sc = 1.0;\n                    if (f < 7) sc = 1 - 0.07 * (f / 7);\n                    else if (f < 12) sc = 0.93 + 0.10 * ((f - 7) / 5);\n                    else if (f < 20) sc = 1.03 - 0.03 * ((f - 12) / 8);\n                    _arrowSquash.ScaleX = sc; _arrowSquash.ScaleY = 2 - sc;\n                }\n                else { _arrowSquash.ScaleX = 1; _arrowSquash.ScaleY = 1; }\n            }\n\n            // badge — gated on the pointer's revealed state (CUA\n            // render_state.rs:275-294): when the arrow is idle-faded or\n            // hidden, the pill cannot render, whatever hover says.\n            bool revealed = _pt.Visible && _pt.IdleAlpha > 0.004;\n            bool hover = revealed && HoverNear();\n            double alpha = revealed ? Math.Max(_pt.BadgeAlpha, hover ? 1.0 : 0.0)\n                                    : 0.0;\n            if (alpha > 0.004)\n            {\n                _pillRoot.Visibility = Visibility.Visible;\n                _pillRoot.Opacity = alpha;\n                double w = _pillCapsule.ActualWidth;\n                double x = _pt.X - w / 2;\n                double y = _pt.Y + 25;\n                x = Math.Max(2, Math.Min(_stageW - w - 2, x));\n                y = Math.Max(2, Math.Min(_stageH - 30, y));\n                Canvas.SetLeft(_pillRoot, x);\n                Canvas.SetTop(_pillRoot, y);\n            }\n            else _pillRoot.Visibility = Visibility.Hidden;\n\n            RenderCue();\n        }\n\n        private bool HoverNear()\n        {\n            try\n            {\n                Native.POINT p;\n                if (!Native.GetCursorPos(out p)) return false;\n                double x = (p.X - _screenLeft) * _pixelToDipX;\n                double y = (p.Y - _screenTop) * _pixelToDipY;\n                double dx = x - _pt.X, dy = y - _pt.Y;\n                return dx * dx + dy * dy < PointerState.HoverRadius * PointerState.HoverRadius;\n            }\n            catch { return false; }\n        }\n\n        // -- action cues -----------------------------------------------------------\n\n        private void PlayCue(string kind)\n        {\n            _cueKind = kind;\n            _cueT = 0;\n            _cue.Children.Clear();\n            _cue.Opacity = 1;\n            // Cues live a little right-down of the arrow centre (canvas 74,67).\n            Canvas cueHost = new Canvas { Width = 0, Height = 0 };\n            Canvas.SetLeft(cueHost, 6); Canvas.SetTop(cueHost, 2);\n            UIElement g = BuildCue(kind);\n            if (g != null) cueHost.Children.Add(g);\n            _cue.Children.Add(cueHost);\n        }\n\n        private void StopCue()\n        {\n            _cueKind = \"\";\n            _cue.Opacity = 0;\n        }\n\n        private void RenderCue()\n        {\n            if (_cueKind.Length == 0) { _cue.Opacity = 0; return; }\n            _cueT += 0.016;\n            bool loop = _cueKind == \"observe\" || _cueKind == \"scroll\" || _cueKind == \"composite\";\n            double dur = _cueKind == \"click\" ? 0.67 : 1.6;\n            if (!loop && _cueT > dur) { StopCue(); return; }\n            double u = (_cueT % 1.6) / 1.6;\n            switch (_cueKind)\n            {\n                case \"click\":\n                    // three rays scaling out + fading (0.67 s)\n                    double cu = Math.Min(1, _cueT / 0.67);\n                    _cue.Opacity = 1 - cu;\n                    break;\n                case \"observe\":\n                    _cue.Opacity = 0.9;\n                    break;\n                case \"scroll\":\n                    _cue.Opacity = 0.9;\n                    break;\n                case \"text\":\n                    _cue.Opacity = (Math.Sin(_cueT * 6) > 0) ? 0.95 : 0.15;   // I-beam blink\n                    break;\n                default:\n                    _cue.Opacity = 0.9;\n                    break;\n            }\n        }\n\n        private UIElement BuildCue(string kind)\n        {\n            Brush white = Brushes.White;\n            switch (kind)\n            {\n                case \"click\":\n                    {\n                        Canvas c = new Canvas { Width = 26, Height = 26 };\n                        for (int i = 0; i < 3; i++)\n                        {\n                            double a = -Math.PI / 3 + i * (Math.PI / 3);   // fan\n                            Line l = new Line\n                            {\n                                X1 = 13 + Math.Cos(a) * 6, Y1 = 13 + Math.Sin(a) * 6,\n                                X2 = 13 + Math.Cos(a) * 12, Y2 = 13 + Math.Sin(a) * 12,\n                                Stroke = white, StrokeThickness = 2.4,\n                                StrokeStartLineCap = PenLineCap.Round,\n                                StrokeEndLineCap = PenLineCap.Round\n                            };\n                            c.Children.Add(l);\n                        }\n                        return c;\n                    }\n                case \"text\":\n                    {\n                        Canvas c = new Canvas { Width = 12, Height = 18 };\n                        Line v = new Line { X1 = 6, Y1 = 1, X2 = 6, Y2 = 17, Stroke = white, StrokeThickness = 1.8 };\n                        Line t1 = new Line { X1 = 2, Y1 = 1, X2 = 10, Y2 = 1, Stroke = white, StrokeThickness = 1.8 };\n                        Line t2 = new Line { X1 = 2, Y1 = 17, X2 = 10, Y2 = 17, Stroke = white, StrokeThickness = 1.8 };\n                        c.Children.Add(v); c.Children.Add(t1); c.Children.Add(t2);\n                        return c;\n                    }\n                case \"scroll\":\n                    {\n                        Canvas c = new Canvas { Width = 16, Height = 22 };\n                        Polyline up = new Polyline { Points = MakePoints(3, 8, 8, 2, 13, 8), Stroke = white, StrokeThickness = 2 };\n                        Polyline dn = new Polyline { Points = MakePoints(3, 14, 8, 20, 13, 14), Stroke = white, StrokeThickness = 2 };\n                        c.Children.Add(up); c.Children.Add(dn);\n                        return c;\n                    }\n                case \"observe\":\n                    {\n                        Canvas c = new Canvas { Width = 24, Height = 12 };\n                        Ellipse e1 = new Ellipse { Width = 9, Height = 9, Stroke = white, StrokeThickness = 1.8, Fill = Brushes.Transparent };\n                        Ellipse e2 = new Ellipse { Width = 9, Height = 9, Stroke = white, StrokeThickness = 1.8, Fill = Brushes.Transparent };\n                        Canvas.SetLeft(e1, 0); Canvas.SetTop(e1, 1);\n                        Canvas.SetLeft(e2, 13); Canvas.SetTop(e2, 1);\n                        Ellipse p1 = new Ellipse { Width = 3, Height = 3, Fill = white };\n                        Ellipse p2 = new Ellipse { Width = 3, Height = 3, Fill = white };\n                        Canvas.SetLeft(p1, 3); Canvas.SetTop(p1, 4);\n                        Canvas.SetLeft(p2, 16); Canvas.SetTop(p2, 4);\n                        c.Children.Add(e1); c.Children.Add(e2); c.Children.Add(p1); c.Children.Add(p2);\n                        return c;\n                    }\n                case \"key\":\n                    {\n                        Canvas c = new Canvas { Width = 16, Height = 16 };\n                        Rectangle k = new Rectangle { Width = 12, Height = 12, RadiusX = 2.5, RadiusY = 2.5, Stroke = white, StrokeThickness = 1.8, Fill = Brushes.Transparent };\n                        Canvas.SetLeft(k, 2); Canvas.SetTop(k, 1);\n                        Ellipse dot = new Ellipse { Width = 3, Height = 3, Fill = white };\n                        Canvas.SetLeft(dot, 6.5); Canvas.SetTop(dot, 6);\n                        c.Children.Add(k); c.Children.Add(dot);\n                        return c;\n                    }\n                case \"navigate\":\n                    {\n                        Canvas c = new Canvas { Width = 22, Height = 14 };\n                        Polyline c1 = new Polyline { Points = MakePoints(2, 2, 9, 7, 2, 12), Stroke = white, StrokeThickness = 2 };\n                        Polyline c2 = new Polyline { Points = MakePoints(10, 2, 17, 7, 10, 12), Stroke = white, StrokeThickness = 2 };\n                        c.Children.Add(c1); c.Children.Add(c2);\n                        return c;\n                    }\n                default:\n                    {\n                        Ellipse d = new Ellipse { Width = 8, Height = 8, Fill = white, Opacity = 0.9 };\n                        Canvas c = new Canvas { Width = 8, Height = 8 };\n                        c.Children.Add(d);\n                        return c;\n                    }\n            }\n        }\n\n        private static PointCollection MakePoints(params double[] xy)\n        {\n            PointCollection pc = new PointCollection();\n            for (int i = 0; i + 1 < xy.Length; i += 2) pc.Add(new Point(xy[i], xy[i + 1]));\n            return pc;\n        }\n\n        // -- windows (shared) ------------------------------------------------------\n\n        private Window NewOverlayWindow(double w, double h)\n        {\n            Window win = new Window\n            {\n                Width = w, Height = h,\n                WindowStyle = WindowStyle.None,\n                AllowsTransparency = true,\n                Background = Brushes.Transparent,\n                // b4o: the permanent Topmost is removed for windows the\n                // pin timer re-places (CUA overlay.rs uses NOTOPMOST +\n                // insert-after; a permanent Topmost would fight it). The\n                // caller decides per window: _stage's creation clears it\n                // below; _bar keeps it (no CUA counterpart, unchanged).\n                Topmost = _keepTopmost,\n                ShowInTaskbar = false,\n                ShowActivated = false,\n                Focusable = false,\n                IsHitTestVisible = false,\n                ResizeMode = ResizeMode.NoResize\n            };\n            win.SourceInitialized += delegate\n            {\n                IntPtr hwnd = new WindowInteropHelper(win).Handle;\n                int ex = Native.GetWindowLongPtrW(hwnd, Native.GWL_EXSTYLE);\n                Native.SetWindowLongPtrW(hwnd, Native.GWL_EXSTYLE,\n                    ex | Native.WS_EX_TRANSPARENT | Native.WS_EX_TOOLWINDOW\n                     | Native.WS_EX_NOACTIVATE);\n                // For the human's eyes only: screenshots and recordings\n                // never photograph the marker (cua-driver's design) — unless\n                // monitoring explicitly asks to keep it in the recording.\n                string cap = Environment.GetEnvironmentVariable(\"AUTOSKILL_OVERLAY_CAPTURE\");\n                string cap2 = Environment.GetEnvironmentVariable(\"AUTOSKILL_INDICATOR_CAPTURE\");\n                if (cap != \"1\" && cap2 != \"1\")\n                    Native.SetWindowDisplayAffinity(hwnd, Native.WDA_EXCLUDEFROMCAPTURE);\n            };\n            return win;\n        }\n\n        // -- commands --------------------------------------------------------------\n\n        private void ReadLoop()\n        {\n            JavaScriptSerializer json = new JavaScriptSerializer();\n            string line;\n            while ((line = Console.In.ReadLine()) != null)\n            {\n                Dictionary<string, object> cmd;\n                try { cmd = json.Deserialize<Dictionary<string, object>>(line); }\n                catch { continue; }\n                Dispatcher.BeginInvoke(new Action(delegate { Handle(cmd); }));\n            }\n            Dispatcher.BeginInvoke(new Action(Shutdown));\n        }\n\n        // -- b4o: CUA's pin_overlay_above port (overlay.rs:1453-1522) ------\n\n        // CUA overlay.rs: the pinned window is placed with HWND_NOTOPMOST\n        // then inserted after GetWindow(target, GW_HWNDPREV) (HWND_TOP when\n        // null); unpinned it is HWND_TOPMOST then HWND_NOTOPMOST. Mirrored\n        // exactly; nothing added.\n        private static readonly IntPtr HWND_TOP = IntPtr.Zero;\n        private static readonly IntPtr HWND_NOTOPMOST = new IntPtr(-2);\n        private static readonly IntPtr HWND_TOPMOST = new IntPtr(-1);\n        private const uint SWP_NOMOVE = 0x0002;\n        private const uint SWP_NOSIZE = 0x0001;\n        private const uint SWP_NOACTIVATE = 0x0010;\n        private const uint SWP_SHOWWINDOW = 0x0040;\n        private const uint SWP_NOOWNERZORDER = 0x0200;\n        private const uint GW_HWNDPREV = 3;\n\n        private IntPtr _pinnedRoot = IntPtr.Zero;\n        private System.Threading.Timer _pinTimer;\n        // b4o: _stage (the cursor) is re-placed by the pin timer, so it\n        // must NOT be permanently topmost; _bar keeps its creation-time\n        // topmost (unchanged behaviour, out of the owner's scope).\n        private bool _keepTopmost = false;\n\n        private void PinAbove(long hwnd)\n        {\n            _pinnedRoot = new IntPtr(hwnd);\n            if (_pinTimer == null)\n            {\n                // overlay.rs:9: the overlay re-places itself every 80 ms.\n                _pinTimer = new System.Threading.Timer(_ => RePlace(), null,\n                    0, 80);\n            }\n        }\n\n        private void RePlace()\n        {\n            try\n            {\n                // b4of items 2-4, mirroring CUA overlay.rs:1295-1350/1444-1522.\n                // The gate is the TRUE cursor state (PointerState: _pt.Visible\n                // + IdleAlpha > 0.004 - the expression the frame loop itself\n                // uses at :1003/:1031; CUA overlay.rs:1303-1314's visible-\n                // or-faded check), NOT _stage.IsVisible (always true). A\n                // cursor not visible or faded -> target None (unpinned).\n                // A dead target (IsWindow false) is unpinned (:1444-1451).\n                // The re-place only runs while the overlay is actually\n                // rendering (a frame with work: _pt.Visible || _pt.InFlight,\n                // the OnFrame condition at :978) - a quiescent overlay\n                // leaves its z-slot untouched (:1339-1350).\n                // b4of2: _pt fields belong to the UI thread - the ONLY\n                // read happens inside the dispatcher delegate below. The\n                // gate is CUA's revealed rule (render_state.rs:273-275,\n                // the exact >= 0.004 comparison) or in flight; once the\n                // idle fade completes, no SetWindowPos at all (overlay.rs\n                // :1339-1350: a quiescent overlay leaves its z-slot\n                // untouched - the unpinned dance is gone).\n                IntPtr target = _pinnedRoot;\n                Dispatcher.BeginInvoke(new Action(delegate\n                {\n                    try\n                    {\n                        bool revealed = _pt.Visible && _pt.IdleAlpha >= 0.004;\n                        bool rendering = revealed || _pt.InFlight;\n                        if (!rendering) return;\n                        IntPtr liveTarget = target;\n                        if (liveTarget != IntPtr.Zero && !Native.IsWindow(liveTarget))\n                            liveTarget = IntPtr.Zero;   // CUA :1444-1451\n                        if (!revealed) liveTarget = IntPtr.Zero;  // CUA :1303-1314\n                        IntPtr cursor = new WindowInteropHelper(_stage).Handle;\n                        if (liveTarget != IntPtr.Zero)\n                        {\n                            // pinned case (overlay.rs:1453-1522)\n                            Native.SetWindowPos(cursor, HWND_NOTOPMOST,\n                                0, 0, 0, 0,\n                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE\n                                | SWP_NOOWNERZORDER);\n                            IntPtr prev = Native.GetWindow(liveTarget, GW_HWNDPREV);\n                            Native.SetWindowPos(cursor,\n                                prev == IntPtr.Zero ? HWND_TOP : prev,\n                                0, 0, 0, 0,\n                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE\n                                | SWP_SHOWWINDOW | SWP_NOOWNERZORDER);\n                        }\n                        else\n                        {\n                            // unpinned case (overlay.rs:1514-1520, CUA's\n                            // exact flags INCLUDING SWP_SHOWWINDOW). _stage\n                            // is never hidden as a window (only the inner\n                            // cursor elements fade), so SHOWWINDOW cannot\n                            // re-show a deliberately hidden window.\n                            Native.SetWindowPos(cursor, HWND_TOPMOST,\n                                0, 0, 0, 0,\n                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE\n                                | SWP_SHOWWINDOW | SWP_NOOWNERZORDER);\n                            Native.SetWindowPos(cursor, HWND_NOTOPMOST,\n                                0, 0, 0, 0,\n                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE\n                                | SWP_SHOWWINDOW | SWP_NOOWNERZORDER);\n                        }\n                    }\n                    catch { /* a decoration must never take the tool down */ }\n                }));\n            }\n            catch { }\n        }\n\n        private void Handle(Dictionary<string, object> cmd)\n        {\n            object opObj; if (!cmd.TryGetValue(\"op\", out opObj)) return;\n            string op = Convert.ToString(opObj);\n            try\n            {\n                if (op == \"move\") MoveCursor(Num(cmd, \"x\"), Num(cmd, \"y\"));\n                else if (op == \"bitmap\")\n                {\n                    byte[] pixels = Convert.FromBase64String(Str(cmd, \"data\"));\n                    if (pixels.Length == 32 * 32 * 4)\n                        _cursor.Source = BitmapSource.Create(32, 32, 96, 96,\n                            PixelFormats.Pbgra32, null, pixels, 32 * 4);\n                }\n                else if (op == \"alpha\") _cursor.Opacity = Math.Max(0, Math.Min(1, Num(cmd, \"value\")));\n                else if (op == \"glow\") GlowFlash();\n                else if (op == \"say\") Say(Str(cmd, \"text\"), Str(cmd, \"state\"));\n                else if (op == \"cursor\") FadeCursor(Bool(cmd, \"on\"));\n                else if (op == \"hidebar\") ShowBar(false);\n                else if (op == \"hide\") { FadeCursor(false); PointerHide(); }\n                else if (op == \"quit\") Shutdown();\n                // -- agent pointer (CUA rebuild) --\n                else if (op == \"pmove\")\n                {\n                    _pt.MoveId = (long)Num(cmd, \"id\");\n                    PointerMove(Num(cmd, \"x\"), Num(cmd, \"y\"));\n                    EmitAccepted(_pt.MoveId, _pt.PlannedLen);\n                }\n                else if (op == \"psnap\") _pt.Snap(ToDipX(Num(cmd, \"x\")), ToDipY(Num(cmd, \"y\")));\n                else if (op == \"pshow\") PointerShow(Bool(cmd, \"on\"));\n                else if (op == \"palpha\") _pt.CmdAlpha = Math.Max(0, Math.Min(1, Num(cmd, \"value\")));\n                else if (op == \"ppulse\")\n                {\n                    // Anchor the pulse at the click target (CUA ClickPulse\n                    // carries coordinates), not at wherever the arrow is.\n                    double px = Num(cmd, \"x\"), py = Num(cmd, \"y\");\n                    if (px != 0 || py != 0) _pt.Snap(ToDipX(px), ToDipY(py));\n                    _pt.Pulse();\n                    HookFrame();\n                }\n                else if (op == \"pbadge\") PointerBadge(cmd);\n                else if (op == \"pin\") PinAbove((long)Num(cmd, \"hwnd\"));\n            }\n            catch { /* a decoration must never take the tool down */ }\n        }\n\n        private double ToDipX(double px) { return (px - _screenLeft) * _pixelToDipX; }\n        private double ToDipY(double px) { return (px - _screenTop) * _pixelToDipY; }\n\n        private void EmitAccepted(long id, double plannedLen)\n        {\n            long eta = (long)(plannedLen / 500.0 * 1000.0);\n            EmitLine(\"{\\\"ev\\\":\\\"accepted\\\",\\\"id\\\":\" + id +\n                     \",\\\"eta_ms\\\":\" + eta + \"}\");\n        }\n\n        private void EmitArrived(long id)\n        {\n            EmitLine(\"{\\\"ev\\\":\\\"arrived\\\",\\\"id\\\":\" + id + \"}\");\n        }\n\n        private void EmitLine(string line)\n        {\n            try { Console.Out.Write(line + \"\\n\"); Console.Out.Flush(); }\n            catch { /* narration must never take the renderer down */ }\n        }\n\n        private void PointerMove(double px, double py)\n        {\n            HookFrame();\n            _pt.MoveTo(ToDipX(px), ToDipY(py), _stageW, _stageH);\n        }\n\n        private void PointerShow(bool on)\n        {\n            HookFrame();\n            if (on) { _pt.RevealedOnce = true; _pt.Reveal(); }\n            else PointerHide();\n        }\n\n        private void PointerHide()\n        {\n            _pt.Visible = false;\n            _pt.IdleAlpha = 0;\n            _pt.BadgeT = 1e9;\n            _pt.ChipsOn = false;\n            StopCue();\n        }\n\n        private void PointerBadge(Dictionary<string, object> cmd)\n        {\n            HookFrame();\n            string phase = Str(cmd, \"phase\");\n            if (phase == \"begin\")\n            {\n                // Narration-only flows (browser verbs) never MoveTo: anchor the\n                // pointer at the stage centre so the badge has a home.\n                if (_pt.X < -100 || _pt.Y < -100)\n                {\n                    _pt.RevealedOnce = true;\n                    _pt.Snap(_stageW / 2 - 11.3, _stageH / 2 - 11.3);\n                }\n                string label = SanitizeLabel(Str(cmd, \"label\"));\n                _pt.BeginBadge(label, Str(cmd, \"delivery\"), Str(cmd, \"target\"),\n                               Str(cmd, \"action\"));\n                ApplyBadgeVisuals();\n                PlayCue(Str(cmd, \"action\"));\n            }\n            else if (phase == \"end\")\n            {\n                _pt.EndBadge();\n                StopCue();\n            }\n        }\n\n        private static string SanitizeLabel(string s)\n        {\n            if (s == null) s = \"\";\n            s = s.Replace(\"\\r\", \" \").Replace(\"\\n\", \" \").Replace(\"\\t\", \" \").Trim();\n            while (s.Contains(\"  \")) s = s.Replace(\"  \", \" \");\n            if (s.Length > 28) s = s.Substring(0, 27) + \"\\u2026\";\n            return s;\n        }\n\n        private void ApplyBadgeVisuals()\n        {\n            _pillLabel.Text = _pt.Label;\n            _chipDelivery.Visibility = _pt.Delivery.Length > 0\n                ? Visibility.Visible : Visibility.Collapsed;\n            _chipTarget.Visibility = _pt.Target.Length > 0\n                ? Visibility.Visible : Visibility.Collapsed;\n            // delivery glyph: background = stack, interactive = window\n            Canvas dg = _pt.Delivery == \"background\" ? GlyphStack() : GlyphWindow();\n            _chipDelivery.Child = dg;\n            // target glyph: browser = globe, desktop = monitor\n            Canvas tg = _pt.Target == \"browser\" ? GlyphGlobe() : GlyphMonitor();\n            _chipTarget.Child = tg;\n            _pillCapsule.Measure(new Size(188, 28));\n            _pillCapsule.Arrange(new Rect(0, 0, _pillCapsule.DesiredSize.Width, 28));\n        }\n\n        private static double Num(Dictionary<string, object> d, string k)\n        {\n            object v; return d.TryGetValue(k, out v) ? Convert.ToDouble(v) : 0;\n        }\n\n        private static string Str(Dictionary<string, object> d, string k)\n        {\n            object v; return d.TryGetValue(k, out v) && v != null\n                ? Convert.ToString(v) : \"\";\n        }\n\n        private static bool Bool(Dictionary<string, object> d, string k)\n        {\n            object v; return d.TryGetValue(k, out v) && v != null\n                && Convert.ToBoolean(v);\n        }\n\n        // -- legacy marker cursor ---------------------------------------------------\n\n        private void MoveCursor(double x, double y)\n        {\n            _cursorPos.X = (x - _screenLeft) * _pixelToDipX;\n            _cursorPos.Y = (y - _screenTop) * _pixelToDipY;\n        }\n\n        private void FadeCursor(bool on)\n        {\n            _cursor.Visibility = on ? Visibility.Visible : Visibility.Hidden;\n        }\n\n        private void GlowFlash()\n        {\n            _glow.BeginAnimation(UIElement.OpacityProperty, null);\n            _glow.Opacity = 0.55;\n            _glow.BeginAnimation(UIElement.OpacityProperty,\n                new DoubleAnimation(0.0, TimeSpan.FromMilliseconds(450)));\n        }\n\n        // -- bar ----------------------------------------------------------------\n\n        private void Say(string text, string state)\n        {\n            Color accent = States.ColorOf(state);\n            ((SolidColorBrush)_barPill.BorderBrush).Color = accent;\n            ((SolidColorBrush)_barDot.Fill).Color = accent;\n            if (!String.IsNullOrEmpty(text)) _barText.Text = text;\n            ShowBar(true);\n            _barIdle.Stop(); _barIdle.Start();\n        }\n\n        private void ShowBar(bool on)\n        {\n            if (on)\n            {\n                if (_bar.Visibility != Visibility.Visible)\n                {\n                    _bar.Visibility = Visibility.Visible;\n                    _barSlide.Y = -12;\n                    _barSlide.BeginAnimation(TranslateTransform.YProperty,\n                        new DoubleAnimation(0, TimeSpan.FromMilliseconds(200))\n                        { EasingFunction = new CubicEase { EasingMode = EasingMode.EaseOut } });\n                    _bar.BeginAnimation(UIElement.OpacityProperty,\n                        new DoubleAnimation(1.0, TimeSpan.FromMilliseconds(200)));\n                }\n            }\n            else if (_bar.Visibility == Visibility.Visible)\n            {\n                DoubleAnimation fade = new DoubleAnimation(0,\n                    TimeSpan.FromMilliseconds(300));\n                fade.Completed += delegate\n                {\n                    _bar.Visibility = Visibility.Hidden;\n                };\n                _bar.BeginAnimation(UIElement.OpacityProperty, fade);\n            }\n        }\n    }\n\n    internal static class Program\n    {\n        [STAThread]\n        private static void Main()\n        {\n            new OverlayApp().Run();\n        }\n    }\n}\n");
